RID TextureStreaming::material_set_textures(RID feedback_rid, const Vector<RID> &p_textures) {
	ERR_NOT_ON_RENDER_THREAD_V(RID());
	MutexLock lock(material_mutex);

	MaterialInfo *info = nullptr;
	if (feedback_rid.is_null()) {
		info = material_info_owner.allocate(feedback_rid);
	} else {
		info = material_info_owner.get_or_null(feedback_rid);
	}

	ERR_FAIL_NULL_V(info, RID());

	if (p_textures.is_empty()) {
		material_info_owner.free(feedback_rid);
		return RID();
	}

	info->textures = p_textures;

	return feedback_rid;
}
